/// <summary>
///    Creates a product variant based on the specified parameters.
/// </summary>
/// <param name="_productMaster">
///    The ID of the product master on which to base the variant.
/// </param>
/// <param name="_searchName">
///    The search name of the new product variant.
/// </param>
/// <param name="_dimensions">
///    A container with dimension attributes and values for the product variant.
/// </param>
/// <param name="_productNumber">
///    The display product number, optional.
/// </param>
/// <returns>
///    The ID of the created product variant.
/// </returns>
public static RefRecId createProductVariant(
    RefRecId _productMaster,
    EcoResProductSearchName _searchName,
    container _dimensions,
    EcoResProductDisplayProductNumber _productNumber)
{
    var refRecid = next createProductVariant(_productMaster, _searchName, _dimensions, _productNumber);

    /// Create inventory modules for the newly created product variant.
    EcoResProductVariantManager::createInventTableModules_AVA(refRecid);

    return refRecid;
}

/// <summary>
/// Creates new inventory modules for the product variant that is being released.
/// </summary>
public static void createInventTableModules_AVA(RefRecId _distinctProductVariantRecId)
{
    InventTableModule inventTableModule;
    EcoResDistinctProductVariant productVariant;
    InventTable inventTable;

    productVariant = EcoResDistinctProductVariant::find(_distinctProductVariantRecId);

    if (!productVariant)
    {
        throw Global::error(strFmt("@AVARUM:Product_VariantNotFound", _distinctProductVariantRecId));
    }

    inventTable = InventTable::findByProduct(productVariant.ProductMaster);

    if (!inventTable)
    {
        throw Global::error(strFmt("@AVARUM:Product_InvenTableForVariantNotFound", productVariant.DisplayProductNumber));
    }

    ttsbegin;     

    inventTableModule = InventTableModule::findByProductVariant_AVA(productVariant.RecId, ModuleInventPurchSales::AVARUMSalesForProductVariants);

    if (!inventTableModule)
    {               
        inventTableModule.initValue();
        inventTableModule.ModuleType = ModuleInventPurchSales::AVARUMSalesForProductVariants;
        inventTableModule.ItemId = productVariant.DisplayProductNumber;
        inventTableModule.UnitId = '';

        if (inventTableModule.validateWrite())
        {
            inventTableModule.insert();
        }
    }

    ttscommit;
}
